  'help.type.security': 'Sicurezza',
  'help.type.other': 'Altro',
  'help.faq.cantLogin.q': 'Non riesco ad accedere al mio account',
  'help.faq.cantLogin.a': 'Assicurati di utilizzare l\'email e la password corrette. Se hai dimenticato la password, clicca su "Hai dimenticato la password?" nella schermata di accesso. Se il problema persiste, crea un ticket di supporto.',
  'help.faq.notReceiving.q': 'Non ricevo email',
  'help.faq.notReceiving.a': 'Controlla prima la tua cartella Spam. Assicurati che il tuo spazio di archiviazione non sia pieno. Se il problema continua, verifica che il mittente abbia l\'indirizzo email corretto e crea un ticket di supporto.',
  'help.faq.cantSend.q': 'Non riesco a inviare email',
  'help.faq.cantSend.a': 'Verifica la tua connessione internet e che l\'indirizzo email del destinatario sia corretto. Controlla se hai allegati troppo grandi (max 25MB). Riprova tra qualche minuto.',
  'help.faq.forgotPassword.q': 'Ho dimenticato la mia password',
  'help.faq.forgotPassword.a': 'Nella schermata di accesso, clicca su "Hai dimenticato la password?" e segui le istruzioni per reimpostare la tua password tramite il tuo indirizzo email di recupero.',
  'help.faq.accountSecurity.q': 'Penso che il mio account sia stato compromesso',
  'help.faq.accountSecurity.a': 'Cambia immediatamente la tua password. Controlla la tua cartella Inviati per messaggi che non hai inviato. Abilita l\'autenticazione a due fattori in Impostazioni > Sicurezza. Se necessario, crea un ticket di supporto urgente.',
  'help.faq.appAccess.q': 'Come accedo all\'app su mobile?',
  'help.faq.appAccess.a': 'Puoi accedere a Chatyy tramite qualsiasi browser mobile su chatyy.com.br, oppure scarica la nostra app dallo store del tuo dispositivo.',

  // Privacy modal
  'privacy.title': 'Informativa sulla Privacy',
  'privacy.subtitle': 'Come proteggiamo e gestiamo i tuoi dati',
  'privacy.lastUpdated': 'Ultimo aggiornamento: Marzo 2026',
  'privacy.dataCollection.title': 'Raccolta Dati',
  'privacy.dataCollection.body': 'Raccogliamo solo le informazioni necessarie per fornire il nostro servizio email: il tuo nome, indirizzo email e il contenuto dei messaggi che invii e ricevi. Non vendiamo né condividiamo i tuoi dati personali con terzi per scopi di marketing.',
  'privacy.dataUsage.title': 'Come Usiamo i Tuoi Dati',
  'privacy.dataUsage.body': 'I tuoi dati vengono utilizzati esclusivamente per gestire e migliorare il servizio email, inclusa la consegna dei messaggi, il filtraggio dello spam, la fornitura di funzionalità basate su AI (con il tuo consenso) e il mantenimento della sicurezza dell\'account.',
  'privacy.dataSecurity.title': 'Sicurezza dei Dati',
  'privacy.dataSecurity.body': 'Utilizziamo la crittografia standard del settore (TLS/SSL) per tutti i dati in transito e a riposo. Le sessioni sono protette con token crittografati e protezione CSRF. Auditiamo regolarmente le nostre pratiche di sicurezza.',
  'privacy.cookies.title': 'Cookie & Memoria Locale',
  'privacy.cookies.body': 'Utilizziamo cookie essenziali e memoria locale per mantenere la tua sessione, ricordare le tue preferenze (tema, lingua) e fornire un\'esperienza fluida. Non utilizziamo cookie di tracciamento di terzi.',
  'privacy.thirdParties.title': 'Servizi di Terzi',
  'privacy.thirdParties.body': 'Potremmo utilizzare servizi di terzi per funzionalità specifiche come le funzionalità AI (Anthropic Claude) e le notifiche push. Questi servizi sono vincolati dalle proprie politiche sulla privacy e trattano solo i dati minimi necessari.',
  'privacy.rights.title': 'I Tuoi Diritti',
  'privacy.rights.body': 'Hai il diritto di accedere, correggere, esportare o eliminare i tuoi dati personali in qualsiasi momento. Puoi gestire i tuoi dati tramite Impostazioni o contattando il nostro team di supporto.',
  'privacy.contact.title': 'Contattaci',
  'privacy.contact.body': 'Per domande relative alla privacy o richieste di dati, contattaci a privacy@chatyy.com.br. Risponderemo entro 30 giorni.',

  // Terms modal
  'terms.title': 'Termini di Servizio',
  'terms.subtitle': 'Linee guida per l\'uso di Chatyy',
  'terms.lastUpdated': 'Ultimo aggiornamento: Marzo 2026',
  'terms.acceptance.title': 'Accettazione dei Termini',
  'terms.acceptance.body': 'Accedendo o utilizzando Chatyy, accetti di essere vincolato da questi Termini di Servizio. Se non sei d\'accordo con una parte di questi termini, non puoi utilizzare il servizio.',
  'terms.services.title': 'Descrizione dei Servizi',
  'terms.services.body': 'Chatyy fornisce servizi di comunicazione email, inclusi invio, ricezione e gestione delle email, insieme a funzionalità basate su AI, integrazione del calendario e capacità di videoconferenza.',
  'terms.accounts.title': 'Account Utente',
  'terms.accounts.body': 'Sei responsabile del mantenimento della sicurezza delle credenziali del tuo account. Non devi condividere la tua password né consentire accessi non autorizzati al tuo account. Devi avere almeno 13 anni per utilizzare questo servizio.',
  'terms.conduct.title': 'Uso Accettabile',
  'terms.conduct.body': 'Accetti di non utilizzare il servizio per inviare spam, malware, phishing o contenuti illegali. Non devi tentare di accedere agli account di altri utenti o interrompere l\'infrastruttura del servizio.',
  'terms.content.title': 'Proprietà dei Contenuti',
  'terms.content.body': 'Mantieni la proprietà di tutti i contenuti che crei e invii tramite il servizio. Non rivendichiamo la proprietà delle tue email o allegati. Potremmo elaborare i contenuti come necessario per fornire il servizio.',
  'terms.limitation.title': 'Limitazione di Responsabilità',
  'terms.limitation.body': 'Chatyy è fornito "così com\'è". Ci impegniamo per un uptime del 99,9% ma non garantiamo un servizio ininterrotto. Non siamo responsabili per danni indiretti, incidentali o consequenziali derivanti dal tuo utilizzo del servizio.',
  'terms.termination.title': 'Cancellazione dell\'Account',
  'terms.termination.body': 'Possiamo sospendere o terminare account che violano questi termini. Puoi eliminare il tuo account in qualsiasi momento tramite Impostazioni. Alla cancellazione, i tuoi dati verranno eliminati entro 30 giorni.',
  'terms.changes.title': 'Modifiche ai Termini',
  'terms.changes.body': 'Potremmo aggiornare questi termini di tanto in tanto. Ti informeremo di modifiche significative via email o tramite notifiche in-app. L\'uso continuato del servizio dopo le modifiche costituisce accettazione dei termini aggiornati.',

